insert into public.industries(id,name) values ('tech','Tech & Software'),('design','Design & Creative'),('business','Business & Finance'),('marketing','Marketing & Sales'),('healthcare','Healthcare'),('education','Education'),('engineering','Engineering'),('other','Other Careers') on conflict(id) do update set name=excluded.name;
insert into public.rooms(slug,name,description,icon,industry_id) values('lounge','The Unemployment Lounge','Job searches, life updates, and everything in between.','☕',null),('tech','Tech & Software','Code, interviews, and the occasional missing semicolon.','⌘','tech'),('design','Design & Creative','Portfolios, feedback, and life outside the brief.','✳','design'),('business','Business & Finance','Spreadsheets closed. Conversation open.','↗','business'),('marketing','Marketing & Sales','A conversation you don’t have to pitch.','◎','marketing'),('healthcare','Healthcare','Some space for the people who care.','♡','healthcare'),('education','Education','There’s always more to talk about.','▤','education'),('engineering','Engineering','Working things out, together.','⚙','engineering'),('other','Other Careers','No neat category? You’re in the right place.','✦','other') on conflict(slug) do update set name=excluded.name,description=excluded.description;
